// @ts-check
// Hand-written Wails v3 binding shim. The Wails v3 generator emits per-method
// files keyed by stable numeric IDs, but we deliberately use Call.ByName so
// the renderer can call any bound Desktop method without regenerating
// bindings after every Go change. The method name matches the Go receiver
// method on github.com/FlameInTheDark/neuropipe/internal/app.Desktop.
//
// This file is the v3 replacement for the previous frontend/wailsjs/go/app/Desktop.js
// generated by Wails v2. It uses the @wailsio/runtime package, which is the
// official v3 frontend runtime.
import { Call } from "@wailsio/runtime";

/**
 * Invoke a bound Desktop method by name. The Go side registers the Desktop
 * service via application.NewService(desktop) in main.go; Wails v3 exposes
 * every exported method on the bound instance through the named-call API.
 *
 * The method name is the fully qualified name Wails v3 generates from the
 * service's package path, type name, and method name:
 *   github.com/FlameInTheDark/neuropipe/internal/app.Desktop.<Method>
 */
const FQN_PREFIX = "github.com/FlameInTheDark/neuropipe/internal/app.Desktop.";

export function call<T>(method: string, ...args: unknown[]): Promise<T> {
  return Call.ByName(`${FQN_PREFIX}${method}`, ...args) as Promise<T>;
}

